DROP TABLE IF EXISTS `attendance`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `attendance` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `date` date NOT NULL,
  `check_in` time DEFAULT NULL,
  `check_out` time DEFAULT NULL,
  `overtime_hours` decimal(4,2) DEFAULT 0.00 COMMENT 'Số giờ làm thêm (OT)',
  `late_minutes` int(11) DEFAULT 0 COMMENT 'Số phút đi muộn',
  `early_minutes` int(11) DEFAULT 0 COMMENT 'Số phút về sớm',
  `status` enum('present','late','early_leave','absent','leave_with_permit') DEFAULT 'present',
  `leave_type` varchar(20) DEFAULT NULL COMMENT 'Loại nghỉ: annual (phép năm), sick (ốm đau), maternity (thai sản), personal (việc riêng), unpaid (không lương)',
  `note` varchar(255) DEFAULT NULL,
  `proposal_id` int(11) DEFAULT NULL COMMENT 'Liên kết đề xuất nghỉ phép',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_employee_date` (`employee_id`,`date`),
  CONSTRAINT `attendance_ibfk_1` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2729 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
