--
-- Table structure for table `branch_workforce_requests`
--

DROP TABLE IF EXISTS `branch_workforce_requests`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `branch_workforce_requests` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `request_code` varchar(50) NOT NULL,
  `branch_id` int(11) NOT NULL,
  `department_id` int(11) DEFAULT NULL,
  `position_id` int(11) DEFAULT NULL,
  `request_type` enum('request_headcount','surplus_relocation','internal_restructure','management_appointment') DEFAULT 'request_headcount',
  `title` varchar(255) NOT NULL,
  `urgency` enum('normal','high','urgent') DEFAULT 'normal',
  `quantity` int(11) DEFAULT 1 COMMENT 'Số lượng nhân sự cần bổ sung/điều chuyển',
  `candidate_id` int(11) DEFAULT NULL COMMENT 'Nhân sự tiến cử hoặc đề xuất luân chuyển (nếu có)',
  `rationale` text NOT NULL COMMENT 'Căn cứ, lý do và giải trình chi tiết',
  `estimated_cost` decimal(15,2) DEFAULT 0.00 COMMENT 'Dự toán ngân sách / phụ cấp hỗ trợ',
  `status` enum('pending','approved','rejected','incorporated') DEFAULT 'pending',
  `reviewed_by` int(11) DEFAULT NULL,
  `reviewed_at` datetime DEFAULT NULL,
  `review_notes` text DEFAULT NULL COMMENT 'Ý kiến phản hồi / phê duyệt từ Ban Nhân sự Tập đoàn',
  `linked_plan_id` int(11) DEFAULT NULL COMMENT 'Liên kết kế hoạch sau khi được tích hợp',
  `created_by` int(11) NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `request_code` (`request_code`),
  KEY `branch_id` (`branch_id`),
  KEY `department_id` (`department_id`),
  KEY `position_id` (`position_id`),
  KEY `candidate_id` (`candidate_id`),
  KEY `linked_plan_id` (`linked_plan_id`),
  KEY `created_by` (`created_by`),
  CONSTRAINT `branch_workforce_requests_ibfk_1` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `branch_workforce_requests_ibfk_2` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `branch_workforce_requests_ibfk_3` FOREIGN KEY (`position_id`) REFERENCES `positions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `branch_workforce_requests_ibfk_4` FOREIGN KEY (`candidate_id`) REFERENCES `employees` (`id`) ON DELETE SET NULL,
  CONSTRAINT `branch_workforce_requests_ibfk_5` FOREIGN KEY (`linked_plan_id`) REFERENCES `transfer_plans` (`id`) ON DELETE SET NULL,
  CONSTRAINT `branch_workforce_requests_ibfk_6` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

