INSERT INTO `branch_workforce_requests` VALUES (1,'DX-CT-2026-001',4,10,14,'request_headcount','Đề xuất bổ sung khẩn cấp 02 Chuyên viên Kho vận & Phân phối Vùng','urgent',2,NULL,'Sản lượng phân phối hàng nông sản và bách hóa tại Hub Cần Thơ tăng 45% trong Q2/2026, kho lạnh vận hành 3 ca liên tục gây quá tải nhân sự.',8000000.00,'approved',1,'2026-10-06 14:37:30','',NULL,1,'2026-04-02 01:30:00','2026-10-06 07:37:30'),(2,'DX-HCM-2026-002',2,4,8,'management_appointment','Đề xuất tiếp nhận Quản lý Cửa hàng Flagship từ Hội sở biệt phái vào','high',1,46,'Chuẩn bị khai trương Flagship Store Quận 1 trong tháng 5/2026, cần nhân sự quản lý có kinh nghiệm vận hành chuẩn mực tập đoàn để đào tạo đội ngũ mới.',5000000.00,'approved',1,'2026-04-03 14:15:00','Đã thẩm định nhu cầu thực tế hợp lý. Đề nghị đưa vào kế hoạch quy hoạch Q2/2026.',NULL,1,'2026-04-02 03:45:00','2026-10-06 07:17:30'),(3,'DX-DNG-2026-003',3,5,6,'surplus_relocation','Đề xuất luân chuyển 01 Chuyên viên SCM sang hỗ trợ Chi nhánh Hải Phòng','normal',1,16,'Sau khi tối ưu hóa tuyến vận tải miền Trung, chi nhánh Đà Nẵng có thể bố trí 01 nhân sự giàu kinh nghiệm sang hỗ trợ Hub Cảng Hải Phòng thiết lập hệ thống WMS.',4000000.00,'incorporated',1,'2026-04-04 09:20:00','Đã tích hợp thành công vào Kế hoạch mở rộng Hải Phòng PLAN-2026-HAI-PHONG.',2,1,'2026-04-03 09:00:00','2026-10-06 07:17:30'),(4,'DX-HP-2026-004',5,11,12,'request_headcount','Xin bổ sung Chuyên viên Pháp chế Hợp đồng Ngoại thương cảng biển','high',1,31,'Khối lượng hợp đồng ngoại thương và lưu kho bãi quốc tế tăng mạnh, cần nhân sự chuyên môn về luật hàng hải và thương mại quốc tế.',4500000.00,'pending',NULL,NULL,NULL,NULL,1,'2026-04-05 04:10:00','2026-10-06 07:17:30'),(5,'DX-BD-2026-005',6,12,4,'internal_restructure','Đề xuất kiện toàn tái cơ cấu bộ phận Giám sát Bán lẻ Bình Dương','normal',2,NULL,'Sáp nhập 2 cụm siêu thị nhỏ thành 1 cụm liên phường để tinh gọn biên chế quản lý và tối ưu hóa chi phí lương tại khu công nghiệp.',0.00,'pending',NULL,NULL,NULL,NULL,1,'2026-04-06 02:00:00','2026-10-06 07:17:30');
/*!40000 ALTER TABLE `branch_workforce_requests` ENABLE KEYS */;
UNLOCK TABLES;

