DROP TABLE IF EXISTS `candidates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `candidates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `candidate_code` varchar(50) NOT NULL COMMENT 'Mã hồ sơ: UV-YYYY-XXX',
  `job_position_id` int(11) NOT NULL COMMENT 'Vị trí ứng tuyển',
  `fullname` varchar(100) NOT NULL COMMENT 'Họ và tên ứng viên',
  `email` varchar(100) NOT NULL COMMENT 'Email liên hệ',
  `phone` varchar(20) NOT NULL COMMENT 'Số điện thoại',
  `gender` enum('Nam','Nu','Khac') DEFAULT 'Nam',
  `birth_date` date DEFAULT NULL COMMENT 'Ngày sinh',
  `education` varchar(255) DEFAULT NULL COMMENT 'Trình độ học vấn & chuyên ngành',
  `experience_years` int(11) DEFAULT 0 COMMENT 'Số năm kinh nghiệm',
  `cv_file` varchar(255) DEFAULT NULL COMMENT 'Tệp CV scan đính kèm',
  `cover_letter` text DEFAULT NULL COMMENT 'Thư xin việc / ghi chú ứng viên',
  `source` enum('website','referral','headhunt','job_board','social','other') DEFAULT 'website' COMMENT 'Nguồn tuyển dụng',
  `stage` enum('applied','screening','interview','offer','hired','rejected') DEFAULT 'applied' COMMENT 'Giai đoạn trong Pipeline',
  `rating` tinyint(4) DEFAULT 3 COMMENT 'Đánh giá năng lực từ 1 đến 5 sao',
  `interview_date` datetime DEFAULT NULL COMMENT 'Lịch hẹn phỏng vấn',
  `interview_notes` text DEFAULT NULL COMMENT 'Biên bản & nhận xét phỏng vấn',
  `hired_employee_id` int(11) DEFAULT NULL COMMENT 'ID nhân viên khi đã chuyển đổi',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `candidate_code` (`candidate_code`),
  KEY `job_position_id` (`job_position_id`),
  KEY `hired_employee_id` (`hired_employee_id`),
  CONSTRAINT `candidates_ibfk_1` FOREIGN KEY (`job_position_id`) REFERENCES `job_positions` (`id`) ON DELETE CASCADE,
  CONSTRAINT `candidates_ibfk_2` FOREIGN KEY (`hired_employee_id`) REFERENCES `employees` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=47 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

