DROP TABLE IF EXISTS `department_kpi_targets`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `department_kpi_targets` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `period_id` int(11) NOT NULL,
  `department_id` int(11) NOT NULL,
  `target_title` varchar(255) NOT NULL,
  `target_description` text DEFAULT NULL,
  `kpi_items_json` longtext DEFAULT NULL,
  `target_budget` decimal(15,2) DEFAULT NULL,
  `assigned_by` int(11) DEFAULT NULL,
  `status` enum('draft','assigned','in_progress','completed') DEFAULT 'assigned',
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `unique_period_dept` (`period_id`,`department_id`),
  KEY `idx_period` (`period_id`),
  KEY `idx_dept` (`department_id`)
) ENGINE=InnoDB AUTO_INCREMENT=16 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

