INSERT INTO `departments` VALUES (1,'Ban Tổng Giám Đốc','BGD','Ban điều hành chiến lược kinh doanh và mở rộng mạng lưới 4.500+ siêu thị, cửa hàng WinMart/WinMart+/WiN',3,1,NULL,1,'2026-09-29 06:56:06'),(2,'Khối Quản Trị Nhân Sự & Đào Tạo','HR','Quản trị nguồn nhân lực chuỗi bán lẻ, tiền lương C&B, phát triển nhân tài và văn hóa WinCommerce',12,1,NULL,2,'2026-09-29 06:56:06'),(3,'Khối Công Nghệ Thông Tin & Số Hóa','IT','Phát triển hạ tầng bán lẻ đa kênh Omni-channel, Cloud ERP, POS và hệ sinh thái WiN Membership',15,1,NULL,4,'2026-09-29 06:56:06'),(4,'Khối Vận Hành Chuỗi Siêu Thị (Retail Ops)','RETAIL','Quản lý và vận hành hệ thống đại siêu thị WinMart, chuỗi cửa hàng tiện ích WinMart+ và WiN',20,2,NULL,3,'2026-09-29 06:56:06'),(5,'Khối Chuỗi Cung Ứng & Trung Tâm Phân Phối (SCM)','SCM','Quản trị chuỗi cung ứng lạnh, hệ thống trung tâm phân phối (DC) và điều phối giao nhận toàn quốc',18,3,NULL,15,'2026-09-29 06:56:06'),(6,'Khối Tài Chính - Kế Toán','FIN','Quản trị dòng tiền, kiểm soát chi phí bán lẻ, kế toán chuỗi và quyết toán thuế tập đoàn',12,1,NULL,6,'2026-09-29 06:56:06'),(7,'Khối Tiếp Thị, Thương Hiệu & WiN Membership','MKT','Chiến dịch thương hiệu WinMart, tiếp thị số, khuyến mại bán lẻ và chăm sóc 10+ triệu hội viên WiN',10,2,NULL,26,'2026-09-29 06:56:06'),(8,'Khối Trải Nghiệm Khách Hàng (CX & Care)','CX','Chăm sóc khách hàng đa kênh, tiếp nhận phản hồi dịch vụ và nâng cao chỉ số hài lòng CSAT/NPS',8,2,NULL,28,'2026-09-29 06:56:06'),(9,'Khối Pháp Chế, An Toàn & Kiểm Soát Tuân Thủ','LEGAL','Pháp chế thương mại, an toàn vệ sinh thực phẩm (ATVSTP) và kiểm soát rủi ro tuân thủ hệ thống',8,1,NULL,30,'2026-09-29 06:56:06'),(10,'Bộ Phận Vận Hành Trung Tâm Phân Phối Cần Thơ','CT_LOG','Vận hành kho tổng và phân phối hàng hóa khu vực Tây Nam Bộ',12,4,NULL,NULL,'2026-10-06 07:17:30'),(11,'Phòng Xuất Nhập Khẩu Cảng Biển Hải Phòng','HP_XNK','Giao nhận cảng biển quốc tế và thông quan hàng hóa phục vụ chuỗi siêu thị',10,5,NULL,NULL,'2026-10-06 07:17:30'),(12,'Chi Nhánh Vận Hành Chuỗi Siêu Thị Bình Dương','BD_RETAIL','Quản lý cụm siêu thị WinMart và WinMart+ khu vực Đông Nam Bộ',15,6,NULL,NULL,'2026-10-06 07:17:30');
