CREATE TABLE `disciplines` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `discipline_code` varchar(50) NOT NULL COMMENT 'Mã biên bản: KL-YYYY-XXX',
  `employee_id` int(11) NOT NULL COMMENT 'Nhân viên bị xử lý kỷ luật',
  `discipline_type` enum('warning','reprimand','salary_raise_delay','demotion','termination') DEFAULT 'warning',
  `title` varchar(255) NOT NULL COMMENT 'Tiêu đề / Hành vi vi phạm',
  `description` text DEFAULT NULL COMMENT 'Nội dung chi tiết vi phạm & kết luận',
  `penalty_amount` decimal(15,2) DEFAULT 0.00 COMMENT 'Số tiền phạt / khấu trừ (nếu có)',
  `decision_number` varchar(100) DEFAULT NULL COMMENT 'Số quyết định kỷ luật',
  `discipline_date` date NOT NULL COMMENT 'Ngày lập biên bản / ban hành quyết định',
  `status` enum('pending','approved','executed','cancelled') DEFAULT 'pending' COMMENT 'Trạng thái quy trình',
  `attachment` varchar(255) DEFAULT NULL COMMENT 'Tệp biên bản scan đính kèm',
  `created_by` int(11) DEFAULT NULL COMMENT 'Người lập biên bản',
  `approved_by` int(11) DEFAULT NULL COMMENT 'Lãnh đạo phê duyệt',
  `approved_at` datetime DEFAULT NULL,
  `executed_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `discipline_code` (`discipline_code`),
  KEY `employee_id` (`employee_id`),
  KEY `created_by` (`created_by`),
  KEY `approved_by` (`approved_by`),
  CONSTRAINT `disciplines_ibfk_1` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE CASCADE,
  CONSTRAINT `disciplines_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `disciplines_ibfk_3` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
