INSERT INTO `disciplines` VALUES (1,'DIS-2026-001',17,'warning','Nhắc nhở nội bộ: Vi phạm quy trình bàn giao chứng từ nhập xuất kho lạnh','Chậm trễ nộp biên bản đối soát kho ngày 05/09, gây ảnh hưởng tiến độ chốt số liệu kế toán tuần',0.00,'KL-AURA/2026/004','2026-09-08','executed',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(2,'DIS-2026-002',22,'reprimand','Khiển trách bằng văn bản: Vắng mặt không phép 02 ngày trong đợt cao điểm mở bán','Tự ý nghỉ việc không báo cáo quản lý trực tiếp trong hai ngày khuyến mãi lớn của siêu thị',1000000.00,'KL-AURA/2026/007','2026-09-12','executed',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(3,'DIS-2026-003',48,'warning','Nhắc nhở: Đi muộn 4 lần trong tháng không có lý do chính đáng','Vi phạm nội quy thời gian làm việc tiêu chuẩn của tập đoàn',500000.00,'KL-AURA/2026/009','2026-09-20','approved',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(4,'DIS-2026-004',60,'reprimand','Khiển trách: Không tuân thủ quy định bảo hộ lao động khi bốc xếp hàng hóa cảng','Không đội mũ bảo hộ khi vận hành xe nâng trong khu vực bến bãi',1000000.00,'KL-AURA/2026/011','2026-09-24','approved',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(5,'DIS-2026-005',73,'salary_raise_delay','Hạ mức hoàn thành nhiệm vụ và trừ 10% thưởng kinh doanh tháng do sai sót kiểm kê','Để xảy ra chênh lệch số lượng kiểm kê thực tế so với sổ sách phần mềm POS',2000000.00,'KL-AURA/2026/012','2026-09-27','pending',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(6,'DIS-2026-006',38,'warning','Nhắc nhở: Không cập nhật trạng thái đơn hàng trên hệ thống Logistics đúng hạn','Làm ảnh hưởng đến chỉ số theo dõi thời gian giao hàng (Lead time) của khách hàng',0.00,'KL-AURA/2026/013','2026-09-15','executed',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(7,'DIS-2026-007',42,'reprimand','Khiển trách: Thái độ phục vụ chưa đạt chuẩn mực văn hóa WinCommerce tại quầy tư vấn','Khách hàng VIP phản ánh về sự thiếu nhiệt tình khi hướng dẫn sử dụng voucher quà tặng',500000.00,'KL-AURA/2026/014','2026-09-18','approved',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(8,'DIS-2026-008',56,'warning','Nhắc nhở: Để hàng hóa tồn đọng tại khu vực nhận hàng ngoài bãi quá 4 giờ','Vi phạm quy định giải phóng mặt bằng kho bãi giờ cao điểm',0.00,'KL-AURA/2026/015','2026-09-22','approved',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(9,'DIS-2026-009',66,'demotion','Đề xuất giáng chức từ Store Supervisor xuống Chuyên viên tư vấn do liên tục không đạt KPI','Không hoàn thành chỉ tiêu doanh thu và quản lý nhân sự trong 3 tháng liên tiếp',0.00,'KL-AURA/2026/016','2026-09-26','approved',NULL,1,1,'2026-10-13 11:06:35','2026-09-29 13:56:06','2026-09-29 06:56:06'),(10,'KL-2026-010',19,'reprimand','Khiển trách vi phạm quy trình bàn giao ca và đối soát tiền mặt','Vi phạm quy định không khóa két sắt cuối ngày ca tối ngày 08/10/2026 tại chi nhánh Đà Nẵng, gây rủi ro an toàn tài sản.',500000.00,'QD-KL-2026/010','2026-10-10','approved',NULL,1,1,'2026-10-13 14:28:12','2026-10-13 14:28:12','2026-10-13 07:28:12'),(11,'KL-2026-011',33,'warning','Cảnh cáo nhắc nhở đi làm muộn 4 lần liên tiếp trong tuần','Đi muộn không báo cáo quản lý trực tiếp trong tuần đầu tháng 10/2026, vi phạm điều 14 Nội quy Lao động.',200000.00,'QD-KL-2026/011','2026-10-12','pending',NULL,1,1,'2026-10-13 14:28:12','2026-10-13 14:28:12','2026-10-13 07:28:12');
