--
-- Table structure for table `evaluation_periods`
--

DROP TABLE IF EXISTS `evaluation_periods`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `evaluation_periods` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL COMMENT 'Mã kỳ đánh giá (VD: PERIOD-2026-Q3)',
  `name` varchar(150) NOT NULL COMMENT 'Tên kỳ đánh giá',
  `type` enum('quarterly','annual','probation','project') NOT NULL DEFAULT 'quarterly',
  `year` int(11) NOT NULL COMMENT 'Năm đánh giá',
  `quarter` tinyint(4) DEFAULT NULL COMMENT 'Quý (1, 2, 3, 4)',
  `start_date` date NOT NULL COMMENT 'Ngày bắt đầu kỳ đánh giá',
  `end_date` date NOT NULL COMMENT 'Ngày kết thúc kỳ đánh giá',
  `self_review_deadline` date DEFAULT NULL COMMENT 'Hạn chót nhân viên tự đánh giá',
  `manager_review_deadline` date DEFAULT NULL COMMENT 'Hạn chót quản lý hoàn thành chấm điểm',
  `status` enum('upcoming','active','closed') NOT NULL DEFAULT 'active',
  `description` text DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `idx_status` (`status`),
  KEY `idx_year_quarter` (`year`,`quarter`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

