INSERT INTO `evaluation_periods` VALUES (1,'PERIOD-2026-Q3','Đánh Giá Hiệu Suất & KPI Toàn Diện Quý 3/2026','quarterly',2026,3,'2026-07-01','2026-09-30','2026-10-10','2026-10-20','active','Kỳ đánh giá KPI quý 3 phục vụ xét thưởng hiệu suất và điều chỉnh thu nhập cuối năm.','2026-10-06 13:40:31','2026-10-06 13:40:31'),(2,'PERIOD-2026-Q2','Đánh Giá Hiệu Suất Quý 2/2026 (Đã Hoàn Tất)','quarterly',2026,2,'2026-04-01','2026-06-30','2026-07-10','2026-07-20','closed','Kỳ đánh giá hiệu suất quý 2/2026 đã chốt số liệu và chi trả thưởng.','2026-10-06 13:40:31','2026-10-06 13:40:31');
