--
-- Table structure for table `evaluations`
--

DROP TABLE IF EXISTS `evaluations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `evaluations` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `evaluation_code` varchar(50) NOT NULL COMMENT 'Mã phiếu đánh giá (VD: DG-2026-Q3-001)',
  `period_id` int(11) NOT NULL COMMENT 'Liên kết evaluation_periods.id',
  `employee_id` int(11) NOT NULL COMMENT 'Nhân sự được đánh giá (employees.id)',
  `template_id` int(11) NOT NULL COMMENT 'Bộ tiêu chí áp dụng (kpi_templates.id)',
  `custom_items_json` longtext DEFAULT NULL,
  `goals_summary` text DEFAULT NULL,
  `reviewer_id` int(11) NOT NULL COMMENT 'Quản lý trực tiếp chấm điểm (employees.id)',
  `status` enum('pending','self_review','manager_review','completed') NOT NULL DEFAULT 'pending',
  `self_score` decimal(5,2) DEFAULT NULL COMMENT 'Điểm tự chấm (Thang 100)',
  `self_scores_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Dữ liệu JSON điểm chi tiết từng tiêu chí tự đánh giá' CHECK (json_valid(`self_scores_json`)),
  `self_notes` text DEFAULT NULL COMMENT 'Nhân viên tự nhận xét',
  `self_submitted_at` datetime DEFAULT NULL,
  `manager_score` decimal(5,2) DEFAULT NULL COMMENT 'Điểm quản lý chấm (Thang 100)',
  `manager_scores_json` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin DEFAULT NULL COMMENT 'Dữ liệu JSON điểm chi tiết từng tiêu chí quản lý chấm' CHECK (json_valid(`manager_scores_json`)),
  `manager_notes` text DEFAULT NULL COMMENT 'Quản lý nhận xét và đề xuất',
  `manager_submitted_at` datetime DEFAULT NULL,
  `final_score` decimal(5,2) DEFAULT NULL COMMENT 'Điểm tổng kết cuối cùng (Thang 100: 30% NV + 70% QL)',
  `rating` enum('outstanding','excellent','good','average','below_average','poor') DEFAULT NULL COMMENT 'Xếp loại',
  `bonus_multiplier` decimal(4,2) NOT NULL DEFAULT 1.00,
  `promotion_recommendation` enum('none','bonus','salary_increase','promotion','training','warning') NOT NULL DEFAULT 'none',
  `hr_approved_at` datetime DEFAULT NULL,
  `hr_approved_by` int(11) DEFAULT NULL,
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  `rating_grade` varchar(10) DEFAULT 'B',
  PRIMARY KEY (`id`),
  UNIQUE KEY `evaluation_code` (`evaluation_code`),
  KEY `idx_period` (`period_id`),
  KEY `idx_employee` (`employee_id`),
  KEY `idx_reviewer` (`reviewer_id`),
  KEY `idx_status` (`status`),
  KEY `idx_rating` (`rating`)
) ENGINE=InnoDB AUTO_INCREMENT=61 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

