INSERT INTO `evaluations` VALUES (1,'DG-2026-Q3-001',1,4,1,'[{\"id\":1,\"criteria_name\":\"Tiến độ & Cam kết bàn giao Sprint\",\"priority_group\":\"A\",\"bsc_pillar\":\"internal_process\",\"description\":\"Hoàn thành các User Story \\/ Task theo cam kết Sprint, không trễ hạn Release\",\"weight\":30,\"target_type\":\"percentage\",\"unit\":\"%\",\"target_value\":\"≥ 95%\",\"calc_direction\":\"higher_better\",\"data_source\":\"Jira \\/ Sprint Burndown\",\"min_threshold\":0,\"max_cap\":120,\"sort_order\":1},{\"id\":2,\"criteria_name\":\"Chất lượng Code & Độ tin cậy hệ thống\",\"priority_group\":\"A\",\"bsc_pillar\":\"internal_process\",\"description\":\"Tỷ lệ Bug nghiêm trọng Production = 0, đạt tiêu chuẩn Clean Architecture và Unit Test coverage\",\"weight\":25,\"target_type\":\"percentage\",\"unit\":\"%\",\"target_value\":\"≥ 85%\",\"calc_direction\":\"higher_better\",\"data_source\":\"SonarQube \\/ Production Logs\",\"min_threshold\":0,\"max_cap\":120,\"sort_order\":2},{\"id\":3,\"criteria_name\":\"Năng lực Kỹ thuật & Code Review\",\"priority_group\":\"B\",\"bsc_pillar\":\"internal_process\",\"description\":\"Review code chất lượng cho đồng đội theo SLA 4h, giải pháp tối ưu thuật toán\",\"weight\":20,\"target_type\":\"percentage\",\"unit\":\"%\",\"target_value\":\"≥ 90%\",\"calc_direction\":\"higher_better\",\"data_source\":\"GitLab \\/ PR Reviews\",\"min_threshold\":0,\"max_cap\":120,\"sort_order\":3},{\"id\":4,\"criteria_name\":\"Bảo mật & Tối ưu hiệu năng Cloud\",\"priority_group\":\"B\",\"bsc_pillar\":\"internal_process\",\"description\":\"Không có lỗ hổng bảo mật OWASP, tuân thủ tối ưu chi phí hạ tầng AWS\\/Docker\",\"weight\":15,\"target_type\":\"rating\",\"unit\":\"Chuẩn\",\"target_value\":\"Đạt chuẩn A\",\"calc_direction\":\"boolean\",\"data_source\":\"AWS CloudWatch & Security Audit\",\"min_threshold\":0,\"max_cap\":120,\"sort_order\":4},{\"id\":5,\"criteria_name\":\"Tinh thần phối hợp & Chia sẻ tri thức\",\"priority_group\":\"C\",\"bsc_pillar\":\"learning_growth\",\"description\":\"Tích cực hỗ trợ đồng đội, tham gia hoặc thuyết trình Tech Talk nội bộ hàng tháng\",\"weight\":10,\"target_type\":\"numeric\",\"unit\":\"Lần\\/Quý\",\"target_value\":\"≥ 1 lần\\/quý\",\"calc_direction\":\"higher_better\",\"data_source\":\"Tech Talk Attendance Sheet\",\"min_threshold\":0,\"max_cap\":120,\"sort_order\":5}]',NULL,1,'pending',NULL,NULL,'Em đã nỗ lực dẫn dắt team hoàn thành toàn bộ tính năng chuyển đổi số đúng tiến độ quý 3.','2026-10-02 10:15:00',NULL,NULL,'Vũ Hoàng Long thể hiện vai trò Tech Lead xuất sắc, có tư duy kiến trúc và gắn kết đội ngũ rất cao. Đề xuất khen thưởng và nâng ngạch Principal Architect.','2026-10-04 16:30:00',NULL,NULL,0.00,'none',NULL,NULL,'2026-09-30 08:00:00','2026-10-19 17:58:22',NULL),(2,'DG-2026-Q3-002',1,7,1,'[{\"id\":1,\"criteria_name\":\"Tiến độ & Cam kết bàn giao Sprint\",\"priority_group\":\"A\",\"bsc_pillar\":\"internal_process\",\"description\":\"Hoàn thành các User Story \\/ Task theo cam kết Sprint, không trễ hạn Release\",\"weight\":30,\"target_type\":\"percentage\",\"unit\":\"%\",\"target_value\":\"≥ 95%\",\"calc_direction\":\"higher_better\",\"data_source\":\"Jira \\/ Sprint Burndown\",\"min_threshold\":0,\"max_cap\":120,\"sort_order\":1},{\"id\":2,\"criteria_name\":\"Chất lượng Code & Độ tin cậy hệ thống\",\"priority_group\":\"A\",\"bsc_pillar\":\"internal_process\",\"description\":\"Tỷ lệ Bug nghiêm trọng Production = 0, đạt tiêu chuẩn Clean Architecture và Unit Test coverage\",\"weight\":25,\"target_type\":\"percentage\",\"unit\":\"%\",\"target_value\":\"≥ 85%\",\"calc_direction\":\"higher_better\",\"data_source\":\"SonarQube \\/ Production Logs\",\"min_threshold\":0,\"max_cap\":120,\"sort_order\":2},{\"id\":3,\"criteria_name\":\"Năng lực Kỹ thuật & Code Review\",\"priority_group\":\"B\",\"bsc_pillar\":\"internal_process\",\"description\":\"Review code chất lượng cho đồng đội theo SLA 4h, giải pháp tối ưu thuật toán\",\"weight\":20,\"target_type\":\"percentage\",\"unit\":\"%\",\"target_