--
-- Table structure for table `job_positions`
--

DROP TABLE IF EXISTS `job_positions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `job_positions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `job_code` varchar(50) NOT NULL COMMENT 'Mã tin: TD-YYYY-XXX',
  `title` varchar(255) NOT NULL COMMENT 'Tiêu đề vị trí tuyển dụng',
  `department_id` int(11) DEFAULT NULL COMMENT 'Phòng ban tiếp nhận',
  `branch_id` int(11) DEFAULT NULL COMMENT 'Chi nhánh làm việc',
  `position_id` int(11) DEFAULT NULL COMMENT 'Chức danh định ngạch',
  `quantity` int(11) DEFAULT 1 COMMENT 'Chỉ tiêu tuyển dụng',
  `salary_range_min` decimal(15,2) DEFAULT 0.00 COMMENT 'Lương tối thiểu (VNĐ)',
  `salary_range_max` decimal(15,2) DEFAULT 0.00 COMMENT 'Lương tối đa (VNĐ)',
  `requirements` text DEFAULT NULL COMMENT 'Yêu cầu năng lực & kinh nghiệm',
  `description` text DEFAULT NULL COMMENT 'Mô tả nhiệm vụ công việc',
  `deadline` date DEFAULT NULL COMMENT 'Hạn nộp hồ sơ',
  `status` enum('open','closed','paused','filled') DEFAULT 'open' COMMENT 'Trạng thái tin tuyển',
  `created_by` int(11) DEFAULT NULL COMMENT 'Người tạo tin',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `job_code` (`job_code`),
  KEY `department_id` (`department_id`),
  KEY `branch_id` (`branch_id`),
  KEY `position_id` (`position_id`),
  KEY `created_by` (`created_by`),
  CONSTRAINT `job_positions_ibfk_1` FOREIGN KEY (`department_id`) REFERENCES `departments` (`id`) ON DELETE SET NULL,
  CONSTRAINT `job_positions_ibfk_2` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE SET NULL,
  CONSTRAINT `job_positions_ibfk_3` FOREIGN KEY (`position_id`) REFERENCES `positions` (`id`) ON DELETE SET NULL,
  CONSTRAINT `job_positions_ibfk_4` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=9 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `job_positions`
--

LOCK TABLES `job_positions` WRITE;
/*!40000 ALTER TABLE `job_positions` DISABLE KEYS */;
INSERT INTO `job_positions` VALUES (1,'JOB-2026-001','Kỹ Sư Trí Tuệ Nhân Tạo & Phân Tích Bán Lẻ (AI & Retail Data Scientist)',3,1,5,2,30000000.00,48000000.00,'Tối thiểu 3 năm kinh nghiệm Python, PyTorch/TensorFlow, Big Data, Demand Forecasting bán lẻ.','Xây dựng thuật toán AI gợi ý giỏ hàng thông minh, tối ưu giá linh hoạt (Dynamic Pricing) chuỗi siêu thị.','2026-11-30','open',1,'2026-09-29 06:56:06'),(2,'JOB-2026-002','Giám Đốc Cửa Hàng Flagship Bitexco Q1 (Store Manager)',4,2,8,3,22000000.00,35000000.00,'Tốt nghiệp Đại học, ít nhất 4 năm quản lý chuỗi bán lẻ cao cấp quy mô > 50 nhân sự.','Chịu trách nhiệm toàn diện doanh số P&L, trải nghiệm dịch vụ khách hàng tại trung tâm thương mại Bitexco.','2026-10-31','open',1,'2026-09-29 06:56:06'),(3,'JOB-2026-003','Trưởng Nhóm Điều Phối Logistics Vùng Mekong',5,4,6,2,18000000.00,26000000.00,'Có kinh nghiệm điều hành kho lạnh và mạng lưới xe tải giao hàng chặng cuối Tây Nam Bộ.','Giám sát điều vận đội xe, tối ưu thời gian giao hàng tươi sống từ kho Cần Thơ về 13 tỉnh Mekong.','2026-11-15','open',1,'2026-09-29 06:56:06'),(4,'JOB-2026-004','Kỹ Sư DevOps / Cloud & Security Senior',3,1,9,2,26000000.00,38000000.00,'Thành thạo Kubernetes, Docker, CI/CD pipeline, AWS/GCP, giám sát hệ thống 24/7.','Thiết kế kiến trúc hạ tầng đám mây có độ sẵn sàng cao phục vụ 500+ điểm bán lẻ toàn quốc.','2026-10-31','open',1,'2026-09-29 06:56:06'),(5,'JOB-2026-005','Chuyên Viên Quản Lý Chuỗi Cung Ứng Hải Phòng (Port Logistics)',5,5,14,3,16000000.00,22000000.00,'Hiểu biết sâu sắc về thủ tục hải quan cảng biển, khai thác kho CFS và vận tải liên phương thức.','Điều phối container hàng nhập khẩu từ Cảng Đình Vũ và Lạch Huyện về tổng kho miền Bắc.','2026-11-30','open',1,'2026-09-29 06:56:06'),(6,'JOB-2026-006','Chuyên Viên Truyền Thông & Tiếp Thị Số (Digital Marketing Lead)',7,2,10,2,18000000.00,28000000.00,'Có kinh nghiệm chạy chiến dịch Performance Marketing chuỗi bán lẻ ngân sách > 500 triệu/tháng.','Xây dựng chiến dịch truyền thông đa kênh Omni-channel thu hút 1 triệu người tiêu dùng mới.','2026-10-15','open',1,'2026-09-29 06:56:06'),(7,'JOB-2026-007','Chuyên Viên Pháp Chế Hợp Đồng Thương Mại',9,1,12,1,18000000.00,25000000.00,'Cử nhân Luật, có thẻ luật sư, 3 năm kinh nghiệm đàm phán hợp đồng thuê mặt bằng bán lẻ.','Rà soát hợp đồng nhượng quyền, mặt bằng kinh doanh và xử lý các tranh chấp thương mại.','2026-11-15','open',1,'2026-09-29 06:56:06'),(8,'JOB-2026-008','Chuyên Viên Chăm Sóc Khách Hàng Cao Cấp (VIP Customer Care)',8,2,13,4,13000000.00,18000000.00,'Giọng nói chuẩn, khéo léo xử lý tình huống, ưu tiên từng làm việc tại khách sạn 5 sao hoặc sàn TMĐT.','Chăm sóc hội viên kim cương, giải quyết phản hồi chất lượng và khảo sát NPS định kỳ.','2026-10-30','open',1,'2026-09-29 06:56:06');
/*!40000 ALTER TABLE `job_positions` ENABLE KEYS */;
