DROP TABLE IF EXISTS `kpi_template_items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `kpi_template_items` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `template_id` int(11) NOT NULL COMMENT 'Liên kết kpi_templates.id',
  `criteria_name` varchar(255) NOT NULL COMMENT 'Tên tiêu chí đánh giá',
  `priority_group` enum('A','B','C') NOT NULL DEFAULT 'B',
  `bsc_pillar` enum('financial','customer','internal_process','learning_growth') NOT NULL DEFAULT 'internal_process',
  `description` text DEFAULT NULL COMMENT 'Chi tiết đo lường và kỳ vọng',
  `weight` decimal(5,2) NOT NULL DEFAULT 20.00 COMMENT 'Tỷ trọng % (Tổng các mục = 100%)',
  `target_type` enum('percentage','numeric','rating','boolean') NOT NULL DEFAULT 'percentage',
  `unit` varchar(50) NOT NULL DEFAULT '%',
  `target_value` varchar(100) DEFAULT NULL COMMENT 'Mục tiêu kỳ vọng (VD: >= 95%, 100 Triệu)',
  `calc_direction` enum('higher_better','lower_better','boolean') NOT NULL DEFAULT 'higher_better',
