DROP TABLE IF EXISTS `kpi_templates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `kpi_templates` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `code` varchar(50) NOT NULL COMMENT 'Mã bộ tiêu chí (VD: KPI-TECH, KPI-RETAIL)',
  `name` varchar(150) NOT NULL COMMENT 'Tên bộ tiêu chí KPI',
  `department_id` int(11) DEFAULT NULL COMMENT 'Khối phòng ban áp dụng (NULL = Toàn công ty)',
  `position_id` int(11) DEFAULT NULL,
  `hierarchy_level` enum('executive','manager','specialist','operational') NOT NULL DEFAULT 'specialist',
  `applicable_positions` text DEFAULT NULL,
  `description` text DEFAULT NULL COMMENT 'Mô tả mục tiêu áp dụng',
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `created_at` datetime DEFAULT current_timestamp(),
  `updated_at` datetime DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `code` (`code`),
  KEY `idx_dept` (`department_id`),
  KEY `idx_status` (`status`)
) ENGINE=InnoDB AUTO_INCREMENT=13 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
