DROP TABLE IF EXISTS `payrolls`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `payrolls` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `employee_id` int(11) NOT NULL,
  `month` int(11) NOT NULL,
  `year` int(11) NOT NULL,
  `contract_type` varchar(20) DEFAULT 'fixed_term' COMMENT 'Loại hợp đồng: probation, fixed_term, indefinite, seasonal',
  `basic_salary` decimal(15,2) NOT NULL DEFAULT 0.00,
  `time_salary` decimal(15,2) DEFAULT 0.00 COMMENT 'Tiền lương thời gian thực tế',
  `work_days` float NOT NULL DEFAULT 0,
  `standard_days` decimal(4,1) DEFAULT 22.0 COMMENT 'Số ngày công chuẩn của tháng (T2-T6)',
  `paid_leave_days` decimal(4,1) DEFAULT 0.0 COMMENT 'Số ngày nghỉ phép có hưởng lương',
  `holiday_days` decimal(4,1) DEFAULT 0.0 COMMENT 'Số ngày nghỉ lễ hưởng nguyên lương',
  `unpaid_days` decimal(4,1) DEFAULT 0.0 COMMENT 'Số ngày nghỉ không hưởng lương',
  `late_early_minutes` int(11) DEFAULT 0 COMMENT 'Tổng số phút đi muộn / về sớm trong tháng',
  `allowance` decimal(15,2) DEFAULT 0.00 COMMENT 'Phụ cấp',
  `contract_allowance` decimal(15,2) DEFAULT 0.00 COMMENT 'Phụ cấp thỏa thuận trong HĐ theo ngày công',
  `bonus` decimal(15,2) DEFAULT 0.00 COMMENT 'Khen thưởng / thưởng hiệu quả trong tháng',
  `ot_weekday_hours` decimal(6,2) DEFAULT 0.00 COMMENT 'Giờ OT ngày thường (150%)',
  `ot_weekend_hours` decimal(6,2) DEFAULT 0.00 COMMENT 'Giờ OT ngày nghỉ cuối tuần (200%)',
  `ot_holiday_hours` decimal(6,2) DEFAULT 0.00 COMMENT 'Giờ OT ngày lễ tết (300%)',
  `ot_pay` decimal(15,2) DEFAULT 0.00 COMMENT 'Tổng tiền làm thêm giờ (OT)',
  `ot_tax_exempt` decimal(15,2) DEFAULT 0.00 COMMENT 'Phần tiền OT được miễn thuế TNCN',
  `gross_salary` decimal(15,2) DEFAULT 0.00 COMMENT 'Tổng thu nhập trước thuế (GROSS)',
  `insurance_salary` decimal(15,2) DEFAULT 0.00 COMMENT 'Mức tiền lương làm căn cứ đóng BHXH/BHYT/BHTN',
  `bhxh_employee` decimal(15,2) DEFAULT 0.00 COMMENT 'BHXH người lao động đóng (8%)',
  `bhyt_employee` decimal(15,2) DEFAULT 0.00 COMMENT 'BHYT người lao động đóng (1.5%)',
  `bhtn_employee` decimal(15,2) DEFAULT 0.00 COMMENT 'BHTN người lao động đóng (1%)',
  `dependents_count` tinyint(4) DEFAULT 0 COMMENT 'Số người phụ thuộc đăng ký giảm trừ',
  `family_deduction` decimal(15,2) DEFAULT 0.00 COMMENT 'Tổng giảm trừ gia cảnh (bản thân + người phụ thuộc)',
  `assessable_income` decimal(15,2) DEFAULT 0.00 COMMENT 'Thu nhập tính thuế TNCN',
  `tax_method` varchar(15) DEFAULT 'progressive' COMMENT 'Phương pháp tính thuế: progressive (lũy tiến), flat10 (khấu trừ 10%)',
  `pit_amount` decimal(15,2) DEFAULT 0.00 COMMENT 'Thuế TNCN phải nộp',
  `deduction` decimal(15,2) DEFAULT 0.00 COMMENT 'Các khoản giảm trừ',
  `compensation_deduction` decimal(15,2) DEFAULT 0.00 COMMENT 'Khấu trừ bồi thường thiệt hại (Điều 102 BLLĐ <= 30% lương)',
  `final_salary` decimal(15,2) NOT NULL DEFAULT 0.00,
  `employer_insurance` decimal(15,2) DEFAULT 0.00 COMMENT 'Doanh nghiệp đóng bảo hiểm & KPCĐ (23.5%)',
  `calc_warnings` text DEFAULT NULL COMMENT 'Cảnh báo vi phạm hoặc ngoại lệ pháp lý',
  `locked_at` datetime DEFAULT NULL COMMENT 'Thời điểm chốt bảng lương',
  `locked_by` int(11) DEFAULT NULL COMMENT 'ID người thực hiện chốt bảng lương',
  `payment_status` enum('pending','paid') DEFAULT 'pending',
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_payroll_period` (`employee_id`,`month`,`year`),
  CONSTRAINT `payrolls_ibfk_1` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1067 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

