INSERT INTO `proposals` VALUES (1,'DX-2026-001',5,'leave','Xin nghỉ phép năm 3 ngày','Đề xuất nghỉ phép năm để giải quyết việc gia đình tại quê Thanh Hóa. Đã bàn giao công việc cho đồng nghiệp Trần Thị Hương Giang.','2026-10-05','2026-10-07','annual',3.0,0.00,'normal','approved',1,'2026-09-28 10:30:00',NULL,NULL,'2026-09-27 09:00:00','2026-09-29 15:20:46'),(2,'DX-2026-002',8,'overtime','Đề xuất tăng ca hoàn thiện dự án Cloud Migration','Cần tăng ca 3 ngày liên tiếp (18:00 - 21:00) để hoàn thiện giai đoạn deployment hệ thống ERP lên AWS Cloud. Đã được Tech Lead phê duyệt về mặt kỹ thuật.','2026-10-01','2026-10-03',NULL,3.0,0.00,'high','pending',NULL,NULL,NULL,NULL,'2026-09-28 14:00:00','2026-09-29 15:20:46'),(3,'DX-2026-003',11,'business_trip','Công tác Chi Nhánh Đà Nẵng khảo sát mặt bằng mới','Đi công tác kết hợp khảo sát và đàm phán hợp đồng thuê mặt bằng cửa hàng flagship mới tại khu vực Ngũ Hành Sơn. Dự kiến chi phí di chuyển + lưu trú: 12.000.000đ.','2026-10-10','2026-10-14',NULL,5.0,12000000.00,'normal','approved',2,'2026-09-29 08:45:00',NULL,NULL,'2026-09-28 16:30:00','2026-09-29 15:20:46'),(4,'DX-2026-004',9,'leave','Xin nghỉ ốm 1 ngày','Bị cảm sốt cao 39°C, cần nghỉ ngơi theo chỉ dẫn bác sĩ phòng khám đa khoa quận Cầu Giấy. Có giấy xác nhận nghỉ ốm đính kèm.','2026-09-29','2026-09-29','sick',1.0,0.00,'urgent','approved',1,'2026-09-29 07:30:00',NULL,NULL,'2026-09-29 06:45:00','2026-09-29 15:20:46'),(5,'DX-2026-005',12,'equipment','Đề xuất cấp màn hình phụ 27 inch cho quản lý cửa hàng','Cần màn hình phụ Dell UltraSharp U2723QE 27\" 4K để theo dõi hệ thống camera an ninh và dashboard bán hàng POS đồng thời. Hiện tại chỉ có 1 màn hình, gây khó khăn trong vận hành.',NULL,NULL,NULL,0.0,8500000.00,'normal','pending',NULL,NULL,NULL,NULL,'2026-09-28 11:00:00','2026-09-29 15:20:46'),(6,'DX-2026-006',16,'salary_raise','Đề xuất xem xét tăng lương theo hiệu suất Q3/2026','Hoàn thành vượt 130% KPI logistics quý 3/2026. Đề xuất điều chỉnh tăng 3.000.000đ/tháng theo chính sách đãi ngộ nhân tài và giữ chân cán bộ chủ chốt khối SCM.',NULL,NULL,NULL,0.0,3000000.00,'high','rejected',1,'2026-09-28 16:00:00','Đợi kết quả đánh giá KPI toàn khối SCM cuối quý 3 trước khi xem xét điều chỉnh. Sẽ tái xem xét vào tháng 11/2026.',NULL,'2026-09-26 09:00:00','2026-09-29 15:20:46'),(7,'DX-2026-007',3,'leave','Nghỉ phép việc riêng 2 ngày','Tham dự lễ tốt nghiệp Thạc sĩ Quản trị Kinh doanh của con gái tại Đại học Kinh Tế TP.HCM. Đã sắp xếp phó phòng phụ trách trong thời gian vắng.','2026-10-15','2026-10-16','personal',2.0,0.00,'low','pending',NULL,NULL,NULL,NULL,'2026-09-29 08:00:00','2026-09-29 15:20:46'),(8,'DX-2026-008',8,'leave','Xin nghỉ phép năm về thăm gia đình miền Trung','Tôi làm đơn này xin phép nghỉ phép thường niên 2 ngày để về giải quyết việc gia đình. Công việc bàn giao cho đồng nghiệp Trần Thị Hương Giang.','2026-10-14','2026-10-15','annual',2.0,0.00,'normal','pending',NULL,NULL,NULL,NULL,'2026-10-12 08:30:00','2026-10-13 14:28:12'),(9,'DX-2026-009',12,'overtime','Đề xuất tăng ca kiểm kê kho hàng định kỳ đầu Quý 4','Kiểm kê toàn diện số lượng hàng hóa và thiết bị tại Trung tâm tiếp vận Cần Thơ phục vụ báo cáo tài chính.','2026-10-10','2026-10-10',NULL,1.0,1800000.00,'high','approved',1,'2026-10-09 14:15:00',NULL,NULL,'2026-10-08 14:15:00','2026-10-13 14:28:12'),(10,'DX-2026-010',15,'business_trip','Công tác kiểm tra chất lượng dịch vụ chi nhánh Hải Phòng','Đoàn công tác 3 ngày đánh giá quy trình phục vụ khách hàng VIP và kiểm định tiêu chuẩn nhận diện thương hiệu.','2026-10-18','2026-10-20',NULL,3.0,6500000.00,'high','pending',NULL,NULL,NULL,NULL,'2026-10-11 10:20:00','2026-10-13 14:28:12'),(11,'DX-2026-011',22,'equipment','Đề xuất trang bị máy in hóa đơn nhiệt tốc độ cao cho quầy thu ngân','Máy in cũ tại cửa hàng Flagship Bitexco hay kẹt giấy giờ cao điểm, ảnh hưởng trải nghiệm khách hàng.','2026-10-09','2026-10-09',NULL,0.0,4200000.00,'urgent','approved',2,'2026-10-10 09:00:00',NULL,NULL,'2026-10-09 09:00:00','2026-10-13 14:28:12'),(12,'DX-2026-012',30,'salary_raise','Đề xuất tăng lương vượt bậc cho Kỹ sư AI Data Senior','Đồng chí đã hoàn thiện hệ thống dự báo nhu cầu tồn kho giảm 18% chi phí lưu kho trong Quý 3/2026.','2026-10-01','2026-10-01',NULL,0.0,5000000.00,'normal','approved',1,'2026-10-06 16:40:00',NULL,NULL,'2026-10-05 16:40:00','2026-10-13 14:28:12'),(13,'DX-2026-013',5,'leave','Xin nghỉ thai sản chế độ 6 tháng','Kính gửi Ban Giám đốc và Phòng Nhân sự, tôi xin nghỉ chế độ thai sản theo quy định luật lao động từ giữa tháng 10.','2026-10-20','2027-04-20','maternity',180.0,0.00,'high','approved',1,'2026-10-08 11:30:00',NULL,NULL,'2026-10-07 11:30:00','2026-10-13 14:28:12'),(14,'DX-2026-014',18,'leave','Nghỉ điều trị ốm sốt theo đơn bác sĩ','Tôi bị sốt xuất huyết cần nhập viện theo dõi 3 ngày, xin đính kèm giấy chỉ định của Bệnh viện Hoàn Mỹ.','2026-10-06','2026-10-08','sick',3.0,0.00,'normal','approved',2,'2026-10-07 07:15:00',NULL,NULL,'2026-10-06 07:15:00','2026-10-13 14:28:12'),(15,'DX-2026-015',27,'other','Đề xuất kinh phí tổ chức teambuilding gắn kết quý 4 phòng Marketing','Chương trình dã ngoại cuối tuần tại Cần Giờ nhằm tái tạo năng lượng cho chiến dịch mua sắm Black Friday & Tết.','2026-10-25','2026-10-26',NULL,2.0,15000000.00,'normal','pending',NULL,NULL,NULL,NULL,'2026-10-12 14:00:00','2026-10-13 14:28:12'),(16,'DX-2026-016',35,'overtime','Đề xuất trực vận hành hệ thống ERP & Máy chủ đêm Chủ Nhật','Nâng cấp phiên bản bảo mật hệ thống thanh toán POS và database cluster.','2026-10-11','2026-10-11',NULL,1.0,2500000.00,'urgent','approved',1,'2026-10-10 17:00:00',NULL,NULL,'2026-10-09 17:00:00','2026-10-13 14:28:12'),(17,'DX-2026-017',41,'leave','Xin nghỉ việc riêng kết hôn','Tôi xin nghỉ phép chế độ kết hôn 3 ngày theo Bộ luật Lao động 2019, từ ngày 15/10 đến 17/10/2026.','2026-10-15','2026-10-17','personal',3.0,0.00,'normal','approved',1,'2026-10-11 09:30:00',NULL,NULL,'2026-10-10 09:30:00','2026-10-13 14:28:12'),(18,'DX-2026-018',50,'equipment','Trang bị máy quét kiểm kho tự động Zebra TC21','Phục vụ quy trình xuất nhập kho chi nhánh Đà Nẵng, đồng bộ tức thời với cơ sở dữ liệu trung tâm.','2026-10-13','2026-10-13',NULL,0.0,8500000.00,'high','pending',NULL,NULL,NULL,NULL,'2026-10-13 08:00:00','2026-10-13 14:28:12');
