DROP TABLE IF EXISTS `rewards`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `rewards` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `reward_code` varchar(50) NOT NULL COMMENT 'Mã quyết định: KT-YYYY-XXX',
  `employee_id` int(11) NOT NULL COMMENT 'Nhân viên được khen thưởng',
  `evaluation_id` int(11) DEFAULT NULL COMMENT 'Liên kết đánh giá KPI',
  `reward_type` enum('bonus','certificate','promotion_bonus','achievement') DEFAULT 'bonus' COMMENT 'Hình thức khen thưởng',
  `title` varchar(255) NOT NULL COMMENT 'Tiêu đề khen thưởng',
  `description` text DEFAULT NULL COMMENT 'Lý do & thành tích cụ thể',
  `amount` decimal(15,2) DEFAULT 0.00 COMMENT 'Tiền thưởng kèm theo (nếu có)',
  `decision_number` varchar(100) DEFAULT NULL COMMENT 'Số quyết định / văn bản ban hành',
  `reward_date` date NOT NULL COMMENT 'Ngày ban hành quyết định',
  `status` enum('pending','approved','executed','rejected') DEFAULT 'pending' COMMENT 'Trạng thái quy trình',
  `attachment` varchar(255) DEFAULT NULL COMMENT 'Tệp văn bản scan đính kèm',
  `created_by` int(11) DEFAULT NULL COMMENT 'Người lập đề xuất',
  `approved_by` int(11) DEFAULT NULL COMMENT 'Lãnh đạo phê duyệt',
  `approved_at` datetime DEFAULT NULL,
  `executed_at` datetime DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `reward_code` (`reward_code`),
  KEY `employee_id` (`employee_id`),
  KEY `created_by` (`created_by`),
  KEY `approved_by` (`approved_by`),
  CONSTRAINT `rewards_ibfk_1` FOREIGN KEY (`employee_id`) REFERENCES `employees` (`id`) ON DELETE CASCADE,
  CONSTRAINT `rewards_ibfk_2` FOREIGN KEY (`created_by`) REFERENCES `users` (`id`) ON DELETE SET NULL,
  CONSTRAINT `rewards_ibfk_3` FOREIGN KEY (`approved_by`) REFERENCES `users` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

