INSERT INTO `rewards` VALUES (1,'REW-2026-001',4,NULL,'achievement','Thành tích xuất sắc triển khai Omni-channel ERP Retail vượt tiến độ 15 ngày','Khen thưởng Tech Lead và đội ngũ kỹ thuật hoàn thành xuất sắc hệ thống đồng bộ dữ liệu toàn quốc',15000000.00,'KT-AURA/2026/015','2026-08-30','executed',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(2,'REW-2026-002',12,NULL,'bonus','Khen thưởng Đạt kỷ lục doanh thu tháng khai trương Flagship Bitexco Q1','Quản lý cửa hàng xuất sắc dẫn dắt doanh thu vượt 145% chỉ tiêu tháng đầu mở bán',10000000.00,'KT-AURA/2026/018','2026-09-10','executed',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(3,'REW-2026-003',15,NULL,'achievement','Sáng kiến tối ưu hóa lộ trình chuỗi cung ứng Bắc - Trung - Nam tiết kiệm 12% chi phí','Tối ưu luồng xe tải lạnh liên vận giúp giảm chi phí nhiên liệu và tỷ lệ hao hụt hàng tươi sống',8000000.00,'KT-AURA/2026/020','2026-09-15','executed',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(4,'REW-2026-004',7,NULL,'bonus','Thưởng giải pháp Tối ưu hóa Database giảm 60% thời gian tải trang POS','Nâng cao trải nghiệm thu ngân tại quầy thanh toán vào giờ cao điểm cuối tuần',6000000.00,'KT-AURA/2026/022','2026-09-18','approved',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(5,'REW-2026-005',26,NULL,'promotion_bonus','Thành tích dẫn dắt Chiến dịch Marketing Mùa Thu đạt 500,000 lượt tương tác','Thưởng nóng trưởng khối tiếp thị và đội ngũ sáng tạo nội dung số',8000000.00,'KT-AURA/2026/024','2026-09-22','approved',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(6,'REW-2026-006',11,NULL,'achievement','Phát triển thành công mạng lưới 10 điểm bán mới tại Miền Trung vượt chỉ tiêu','Hoàn tất bàn giao và đưa vào vận hành chuỗi cửa hàng đúng tiến độ',12000000.00,'KT-AURA/2026/025','2026-09-25','pending',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(7,'REW-2026-007',35,NULL,'certificate','Khen thưởng Giám Đốc Chi Nhánh Hải Phòng vận hành Hub Cảng Biển an toàn tuyệt đối','Đạt chứng chỉ chuẩn an toàn lao động và chuỗi cung ứng không để xảy ra sự cố',7000000.00,'KT-AURA/2026/026','2026-09-26','pending',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(8,'REW-2026-008',2,NULL,'achievement','Đạt chứng chỉ quốc tế SHRM-SCP & Đổi mới quy trình đánh giá năng lực KPI','Ứng dụng khung năng lực mới giúp nâng cao năng suất làm việc tập đoàn',10000000.00,'KT-AURA/2026/027','2026-09-28','pending',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(9,'REW-2026-009',18,NULL,'bonus','Khen thưởng cán bộ bán lẻ tiêu biểu quý 3 tại Chi nhánh Đà Nẵng','Đạt danh hiệu quản lý xuất sắc nhất vùng Duyên hải Nam Trung Bộ',5000000.00,'KT-AURA/2026/028','2026-09-20','executed',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(10,'REW-2026-010',20,NULL,'achievement','Khen thưởng Trung tâm Phân phối Mekong vận hành ổn định 100% chuyến xe lạnh','Không có đơn vị nào chậm hàng vượt quá 1 giờ trong toàn quý 3',8000000.00,'KT-AURA/2026/029','2026-09-21','executed',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(11,'REW-2026-011',28,NULL,'bonus','Thưởng nóng Trưởng Khối Chăm Sóc Khách Hàng đạt điểm hài lòng CSAT 96%','Giải quyết triệt để 100% khiếu nại khách hàng trong vòng 24 giờ',6000000.00,'KT-AURA/2026/030','2026-09-23','approved',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(12,'REW-2026-012',30,NULL,'certificate','Khen thưởng Khối Pháp Chế đàm phán thành công hợp đồng thuê mặt bằng 20 năm','Tiết kiệm hơn 3 tỷ đồng chi phí thuê bất động sản thương mại cho tập đoàn',10000000.00,'KT-AURA/2026/031','2026-09-24','approved',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(13,'REW-2026-013',45,NULL,'promotion_bonus','Thưởng bổ nhiệm Giám Đốc Chi Nhánh Bình Dương đưa vào vận hành 5 điểm bán','Hoàn thành khai trương chuỗi siêu thị đúng hạn cam kết với đối tác Becamex',9000000.00,'KT-AURA/2026/032','2026-09-26','pending',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(14,'REW-2026-014',52,NULL,'bonus','Khen thưởng Chuyên viên Tuyển dụng thu hút thành công 25 nhân tài kỹ thuật cao','Rút ngắn 30% thời gian tuyển dụng (Time-to-Hire) các vị trí khó',5000000.00,'KT-AURA/2026/033','2026-09-27','pending',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(15,'REW-2026-015',68,NULL,'achievement','Khen thưởng Sáng kiến đóng gói hàng tươi sống giảm 20% phát thải bao bì nhựa','Đạt giải Nhất cuộc thi Sáng kiến Xanh (Green Retail) nội bộ toàn tập đoàn',7000000.00,'KT-AURA/2026/034','2026-09-28','pending',NULL,1,1,'2026-09-29 13:56:06','2026-09-29 13:56:06','2026-09-29 06:56:06'),(16,'KT-2026-016',3,NULL,'achievement','Khen thưởng Sáng kiến Tối ưu Hóa Quy trình Vận hành Chuỗi Bán lẻ','Đã có sáng kiến cải tiến quy trình giao vận nội bộ, tiết kiệm hơn 450 triệu đồng chi phí logistics trong 9 tháng đầu năm 2026.',15000000.00,'QD-KT-2026/016','2026-10-05','executed',NULL,1,1,'2026-10-13 14:28:12','2026-10-13 14:28:12','2026-10-13 07:28:12'),(17,'KT-2026-017',7,NULL,'bonus','Thưởng Nóng Đạt Doanh Số Kỷ Lục Tuần Khai Trương Cửa Hàng Flagship','Tập thể quản lý và chuyên viên tư vấn chi nhánh TP.HCM hoàn thành 185% chỉ tiêu doanh thu tuần mở bán đầu tiên.',10000000.00,'QD-KT-2026/017','2026-10-08','approved',NULL,1,1,'2026-10-13 14:28:12','2026-10-13 14:28:12','2026-10-13 07:28:12'),(18,'KT-2026-018',14,NULL,'certificate','Vinh danh Nhân Viên Xuất Sắc Nhất Tháng 9/2026 Khối Dịch Vụ Khách Hàng','Đạt điểm đánh giá mức độ hài lòng khách hàng CSAT 99.4%, giải quyết 100% khiếu nại trong vòng 2 giờ làm việc.',5000000.00,'QD-KT-2026/018','2026-10-02','executed',NULL,1,1,'2026-10-13 14:28:12','2026-10-13 14:28:12','2026-10-13 07:28:12'),(19,'KT-2026-019',25,NULL,'bonus','Thưởng Đạt Chứng Chỉ Chuyên Nghiệp Quốc Tế AWS DevOps Pro','Khuyến khích tinh thần tự học tập và nâng cao năng lực chuyên môn theo chính sách phát triển nhân tài của WinCommerce.',8000000.00,'QD-KT-2026/019','2026-10-11','pending',NULL,1,1,'2026-10-13 14:28:12','2026-10-13 14:28:12','2026-10-13 07:28:12');
